@startuml

class Gym {
  + ComputeMonthlyBalance(d : date) : int
  + ComputeAnnualBalance(y : int) : int
  + SendArrearsReminders()
  + SendMedicalCheckReminders()
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class Subscription {
  + startDate : date
}

class MonthlySubscription extends Subscription {
}

class AnnualSubscription extends Subscription {
}

class Service {
  + name : string
  + additionalCost : float
}

class WorkoutPlan {
  + visitsPerWeek : int
}

class WorkoutPlanExercise {
  + exercise : string
  + repetitions : int
  + frequency : string
}

class MedicalCheck {
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
  + date : date
}

class MedicalStaff {
}

class Diet {
}

Customer "1" -- "1" Subscription
Customer "1" -- "0..*" Service
Customer "1" -- "0..1" WorkoutPlan
Customer "0..1" -- "0..*" MedicalCheck
MedicalStaff "1" -- "0..*" Customer : assists
MedicalStaff "1" -- "0..*" Diet : defines
MedicalStaff "1" -- "0..*" MedicalCheck : performs

Subscription "1" -- "1" Gym
Service "0..*" -- "1" Gym
MedicalStaff "1" -- "1" Gym

WorkoutPlan "1" *-- "1..*" WorkoutPlanExercise

@enduml

